-- Reversão manual (com backup e autorização). Remove contratos, financeiro, suporte, manutenção, alertas e notificações.
DROP TABLE IF EXISTS "Notification", "NotificationRecipient", "AutomationRun", "Alert", "AlertRule", "MaintenancePlan", "WorkOrderPart", "WorkOrder", "TicketEvent", "Ticket", "SlaPolicy", "PeriodClosing", "TaxRule", "FinancialEntry", "ContractVersion", "ContractSite", "Contract", "Attachment" CASCADE;
DROP TYPE IF EXISTS "NotificationStatus", "NotificationChannel", "AlertStatus", "AlertSeverity", "AlertKind", "MaintenanceTrigger", "WorkOrderStatus", "WorkOrderType", "TicketEventKind", "TicketStatus", "TicketOrigin", "TicketPriority", "TicketCategory", "ClosingStatus", "EntrySource", "EntryStatus", "EntryCategory", "EntryKind", "SettlementBase", "ContractVersionStatus", "ContractVersionKind", "ContractStatus";
